import React, { useState, useCallback } from 'react';
import './App.css';
import ChatPanel from './components/ChatPanel';
import DesignCanvas from './components/DesignCanvas';
import PropertiesPanel from './components/PropertiesPanel';

function App() {
  const [selectedElement, setSelectedElement] = useState(null);
  const [canvasElements, setCanvasElements] = useState([]);
  const [chatMessages, setChatMessages] = useState([{
    role: 'assistant',
    content: 'ривет! Я помогу создать дизайн интерфейса.'
  }]);

  const handleElementSelect = useCallback((element) => {
    setSelectedElement(element);
  }, []);

  const handleCanvasClick = useCallback(() => {
    setSelectedElement(null);
  }, []);

  return (
    <div className="app">
      <ChatPanel messages={chatMessages} onSendMessage={() => {}} />
      <DesignCanvas elements={canvasElements} selectedElement={selectedElement} onElementSelect={handleElementSelect} onCanvasClick={handleCanvasClick} onElementUpdate={() => {}} />
      {selectedElement && <PropertiesPanel element={selectedElement} onElementUpdate={() => {}} onClose={() => setSelectedElement(null)} />}
    </div>
  );
}

export default App;
